#!/bin/bash
# generated by ADIT 0.1.0a1. Runs the strain runs one by one (they are independent, so a failure does not stop the rest)
cd "$(dirname "$0")"
failed=""
for d in e0 e1_-0.005 e1_+0.005 e4_-0.005 e4_+0.005; do
  echo "== $d"
  bash "$d/submit.sh" || failed="$failed $d"
done
if [ -n "$failed" ]; then echo "failed:$failed" >&2; exit 1; fi
